import{_ as n}from"./chunks/Reptor_Bike.DnvosJou.js";import{_ as t}from"./chunks/Bildlogo_SysLeaks.B5zaKZH-.js";import{_ as i,o as r,c as s,ap as a}from"./chunks/framework.CuFS6FqL.js";const b=JSON.parse('{"title":"Was wir anbieten","description":"Überblick über unsere offensiven Security-Services, unseren effizienten Pentest-Ansatz und Leistungen, die wir nicht anbieten.","frontmatter":{"title":"Was wir anbieten","description":"Überblick über unsere offensiven Security-Services, unseren effizienten Pentest-Ansatz und Leistungen, die wir nicht anbieten."},"headers":[],"relativePath":"de/was-wir-anbieten.md","filePath":"de/was-wir-anbieten.md"}'),o={name:"de/was-wir-anbieten.md"};function u(d,e,l,h,c,f){return r(),s("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /de/was-wir-anbieten.md for this page in Markdown format</div><h1 id="was-wir-anbieten" tabindex="-1">Was wir anbieten <a class="header-anchor" href="#was-wir-anbieten" aria-label="Permalink to &quot;Was wir anbieten&quot;">​</a></h1><p>Wir bieten offensive Security-Services für Kunden im DACH-Raum und darüber hinaus. Unsere Spezialisierungen sind interne Firmennetzwerke (Active Directory, Entra ID und Azure Cloud), externe Infrastrukturen und Web Security. Mit diesem klaren Fokus helfen wir euch, reale Risiken zu finden und zu beheben.</p><p>Wir arbeiten effizient (und halten eure Kosten niedrig) mit einem Ansatz zwischen Grey- und White-Box, einem angemessenen Zeitrahmen und, wo sinnvoll, vereinbarten Leg-ups wie z. B. einem Assumed-Breach-Startpunkt statt langwieriger und kostspieliger verdeckter End-to-End-Kampagnen.</p><h2 id="leistungen-die-wir-anbieten" tabindex="-1">Leistungen, die wir anbieten <a class="header-anchor" href="#leistungen-die-wir-anbieten" aria-label="Permalink to &quot;Leistungen, die wir anbieten&quot;">​</a></h2><ul><li><a href="#assumed-breach-assessments">Assumed-Breach-Assessments</a></li><li><a href="#active-directory-pentests">Active-Directory-Pentests</a></li><li><a href="#entra-id-und-azure-cloud-assessments">Entra-ID- und Azure-Cloud-Assessments</a></li><li><a href="#pentests-externer-infrastrukturen">Pentests externer Infrastrukturen</a></li><li><a href="#pentests-von-web-applikationen">Pentests von Web-Applikationen</a></li><li><a href="#angriffserkennungs-und-response-tests">Angriffserkennungs- und Response-Tests</a></li><li><a href="#passwortanalyse">Passwortanalyse</a></li><li><a href="#lasttests">Lasttests</a></li></ul><h3 id="assumed-breach-assessments" tabindex="-1">Assumed-Breach-Assessments <a class="header-anchor" href="#assumed-breach-assessments" aria-label="Permalink to &quot;Assumed-Breach-Assessments&quot;">​</a></h3><p>Tests von einem Startpunkt aus, an dem ein Angreifer bereits im Netz sein könnte, z. B. Standard-Domain-User, kompromittierte Workstation oder vereinbarter interner Foothold. Die initiale Kompromittierungsphase liegt außerhalb des Scopes. Von dort aus arbeiten wir auf die für den Scope vereinbarten Ziele hin, z. B. Erreichen von Domain Admin, Zugriff auf ein definiertes Zielsystem oder Exfiltration bestimmter Daten. Auf Wunsch orientieren wir Techniken an bekannten Threat-Actor-TTPs.</p><h3 id="active-directory-pentests" tabindex="-1">Active-Directory-Pentests <a class="header-anchor" href="#active-directory-pentests" aria-label="Permalink to &quot;Active-Directory-Pentests&quot;">​</a></h3><p>Pentests von on-prem und hybriden Active-Directory-Umgebungen. Wir prüfen die Angriffspfade und Fehlkonfigurationen, die von Ransomware-Akteuren und Angreifern mit bereits bestehendem Foothold (z. B. einer kompromittierten Workstation oder einem kompromittierten Gerät) typischerweise ausgenutzt werden. Das Ergebnis ist ein klares Bild davon, wie sich ein Angriff von einem einzelnen Endpoint bis zu euren sensibelsten Systemen ausbreiten würde.</p><h3 id="entra-id-und-azure-cloud-assessments" tabindex="-1">Entra-ID- und Azure-Cloud-Assessments <a class="header-anchor" href="#entra-id-und-azure-cloud-assessments" aria-label="Permalink to &quot;Entra-ID- und Azure-Cloud-Assessments&quot;">​</a></h3><p>Identitäts- und Konfigurationsprüfung von Microsoft Entra ID und Azure, inklusive hybrider Szenarien, in denen Entra ID und on-prem AD ineinandergreifen. Wir prüfen Identitätsrisiken, Zugriffsrichtlinien und Angriffspfade zwischen Cloud- und On-Premises-Identitäten, die reale Angreifer für Lateral Movement und Privilege Escalation nutzen. Das Ergebnis zeigt, wie sich ein kompromittierter Cloud-Account auf eure On-Premises-Umgebung auswirken könnte und umgekehrt.</p><h3 id="pentests-externer-infrastrukturen" tabindex="-1">Pentests externer Infrastrukturen <a class="header-anchor" href="#pentests-externer-infrastrukturen" aria-label="Permalink to &quot;Pentests externer Infrastrukturen&quot;">​</a></h3><p>Pentests eurer externen Angriffsoberfläche: exponierte Dienste, Patch-Lücken, Fehlkonfigurationen und Wege ins Netz. Häufig kombiniert mit AD- oder Entra-ID-Pentests für ein vollständiges Bild von extern nach intern, sodass ihr nicht nur seht, was aus dem Internet erreichbar ist, sondern auch, wohin es intern führt.</p><h3 id="pentests-von-web-applikationen" tabindex="-1">Pentests von Web-Applikationen <a class="header-anchor" href="#pentests-von-web-applikationen" aria-label="Permalink to &quot;Pentests von Web-Applikationen&quot;">​</a></h3><p>Manuelle Pentests von Web-Applikationen und APIs nach gängigen Best Practices wie dem OWASP Testing Guide. Wir testen mindestens Grey-Box mit authentifiziertem Zugang und können auf Wunsch auf White-Box mit Source-Code-Review erweitern. Der Schwerpunkt liegt auf Findings, die euer konkretes Risikomodell betreffen, inklusive Geschäftslogik, Authentifizierung und Autorisierung, Datenverarbeitung und relevanter Integrationen.</p><h3 id="angriffserkennungs-und-response-tests" tabindex="-1">Angriffserkennungs- und Response-Tests <a class="header-anchor" href="#angriffserkennungs-und-response-tests" aria-label="Permalink to &quot;Angriffserkennungs- und Response-Tests&quot;">​</a></h3><p>Ausführung realistischer Angriffstechniken in eurer Umgebung, damit ihr prüfen könnt, ob SOC, SIEM und Response-Prozesse sie erkennen und handhaben. Wir stimmen uns eng mit eurem Blue Team ab und berichten, welche Techniken erkannt wurden, welche durchgekommen sind und wo Detection-Regeln nachgeschärft werden können. Das Ergebnis ist konkretes, technikbezogenes Feedback für euer Detection Engineering.</p><h3 id="passwortanalyse" tabindex="-1">Passwortanalyse <a class="header-anchor" href="#passwortanalyse" aria-label="Permalink to &quot;Passwortanalyse&quot;">​</a></h3><p>Analyse der Passwort-Hygiene, z. B. in Active Directory: schwache Passwörter, gängige Muster, Wiederverwendung und Schwächen in den Passwortrichtlinien. Ein fokussierter, effizienter Weg, um Accounts und Richtlinien mit Handlungsbedarf zu identifizieren. Sinnvoll vor oder begleitend zu einem Pentest, da schwache Zugangsdaten nach wie vor zu den häufigsten Einstiegspunkten realer Angriffe gehören.</p><h3 id="lasttests" tabindex="-1">Lasttests <a class="header-anchor" href="#lasttests" aria-label="Permalink to &quot;Lasttests&quot;">​</a></h3><p>Performance- und Stabilitätstests von Web-Applikationen unter Last, getrennt von Schwachstellensuche und vorab abgestimmt, damit es zu keinen ungewollten Auswirkungen kommt. Wir helfen euch zu verstehen, wie sich eure Anwendung unter realistischer und Spitzenlast verhält und wo Engpässe, Fehler oder Stabilitätsprobleme auftreten. Sinnvolle Ergänzung zu Security-Tests bei Anwendungen, die echtem Nutzer-Traffic standhalten müssen.</p><h2 id="was-wir-nicht-anbieten" tabindex="-1">Was wir nicht anbieten <a class="header-anchor" href="#was-wir-nicht-anbieten" aria-label="Permalink to &quot;Was wir nicht anbieten&quot;">​</a></h2><p>Wir sind Experten für offensive Security. Das beste Wissen in einer Domäne erfordert klaren Fokus.</p><p>Deshalb bieten wir nicht an:</p><ul><li>SOC-/SIEM-Dienste</li><li>Incident Response</li><li>ISMS-Beratung</li><li>CISO as a Service</li><li>Awareness-Schulungen</li></ul><p>Für Leistungen außerhalb unseres Scopes können wir Partner empfehlen. Wir nehmen keine Referral-Fees.</p><h2 id="weitere-projekte" tabindex="-1">Weitere Projekte <a class="header-anchor" href="#weitere-projekte" aria-label="Permalink to &quot;Weitere Projekte&quot;">​</a></h2><p>Aus unserer täglichen Pentest-Arbeit sind zwei Produkte entstanden, die wir als eigene Services betreiben: SysReptor, unsere Plattform für Pentest-Reporting, und SysLeaks, unser Service für Data-Leak-Monitoring.</p><div style="display:flex;justify-content:center;flex-wrap:wrap;"><a href="https://docs.sysreptor.com" target="_blank" style="display:flex;justify-content:center;"><figure style="width:15em;margin:0.5em;"><img alt="SysReptor Pentest Reporting" src="'+n+'"><figcaption>SysReptor Pentest Reporting</figcaption></figure></a><a href="https://sysleaks.com" target="_blank" style="display:flex;justify-content:center;"><figure style="width:15em;margin:0.5em;"><img alt="SysLeaks" src="'+t+'"><figcaption>SysLeaks Data Leak Monitoring</figcaption></figure></a></div>',30)])])}const k=i(o,[["render",u]]);export{b as __pageData,k as default};
